-- IDENTITY.sql — the identity read surface every reader (this app and any service
-- granted it) reads: one thin view per identity table, minus its secret columns, plus
-- the rule columns (contracts IDENTITY_VIEWS, cross-repository contract §2).
-- Generated by scripts/render-schema.mjs (npm run render:schema) from the auth
-- package (identity-store/views); never edit by hand. These are exactly the view
-- statements the identity host's boot runs (ensureIdentitySchema), with the
-- default schemas: base tables in auth, the app's admission rows in app, the views
-- in identity. A reader's tests may apply a byte-for-byte copy, so a change here is a
-- change for every reader.
--
-- The grant an operator gives a reader's database role (any name: another service's, the
-- app's in a split-role database), and nothing on any other Artifactbin schema or table:
--
--   GRANT USAGE ON SCHEMA identity TO <reader role>;
--   GRANT SELECT ON ALL TABLES IN SCHEMA identity TO <reader role>;
--   ALTER DEFAULT PRIVILEGES FOR ROLE <identity role> IN SCHEMA identity GRANT SELECT ON TABLES TO <reader role>;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'identity') THEN CREATE SCHEMA identity; END IF; END $$;

CREATE OR REPLACE VIEW identity.users AS
  SELECT u.id, u.email, u.kind, u.parent_user_id, u.expires_at, u.merged_into_user_id, u.name, u.username, u.image_key, u.auto_accept_mentions, u.welcome_pending, u.test_account, u.created_at,
    COALESCE((SELECT ((u.kind='account' AND u.email IS NOT NULL) OR (u.kind = 'testuser' AND (u.expires_at IS NULL OR u.expires_at > now()) AND EXISTS
  (SELECT 1 FROM auth.users parent WHERE parent.id = u.parent_user_id AND parent.kind = 'account' AND parent.email IS NOT NULL))) AND (s.deployment_mode = 'public' OR (EXISTS (SELECT 1 FROM app.deployment_members dm WHERE dm.user_id=u.id)
  OR EXISTS (SELECT 1 FROM auth.users tu JOIN app.deployment_members pm ON pm.user_id=tu.parent_user_id JOIN app.deployment_state ds ON ds.id='company' AND ds.setup_complete=true
   WHERE tu.id=u.id AND (tu.kind = 'testuser' AND (tu.expires_at IS NULL OR tu.expires_at > now()) AND EXISTS
  (SELECT 1 FROM auth.users parent WHERE parent.id = tu.parent_user_id AND parent.kind = 'account' AND parent.email IS NOT NULL)))))
      FROM app.identity_settings s WHERE s.id = 'installation'), false) AS active
  FROM auth.users u;

CREATE OR REPLACE VIEW identity.tokens AS
  SELECT t.id, t.name, t.user_id, t.client_harness, t.audience, t.scope, t.request_authority, t.created_at, t.deleted_at, t.expires_at, t.last_used_at,
    array_remove(regexp_split_to_array(coalesce(t.scope, ''), '\s+'), '') AS scopes,
    ((t.deleted_at IS NULL AND (t.expires_at IS NULL OR t.expires_at>now()) AND (COALESCE(t.audience,'')='' OR EXISTS (SELECT 1 FROM auth.credentials member
      JOIN auth.credentials family ON family.kind='refresh_family' AND family.credential_hash=member.group_id AND family.deleted_at IS NULL
      WHERE COALESCE(t.audience,'')<>'' AND member.kind='refresh_token' AND member.payload->>'access_token_id'=t.id
        AND (family.payload->>'session_id' IS NULL OR EXISTS (SELECT 1 FROM auth.session bound WHERE bound.id=family.payload->>'session_id' AND bound."expiresAt">now()))
        AND NOT EXISTS (
          SELECT 1 FROM auth.credentials sibling LEFT JOIN auth.tokens access ON access.id=sibling.payload->>'access_token_id'
          WHERE sibling.kind='refresh_token' AND sibling.group_id=member.group_id
            AND (sibling.deleted_at IS NOT NULL OR access.id IS NULL OR access.deleted_at IS NOT NULL))))) AND t.user_id IS NOT NULL
      AND EXISTS (SELECT 1 FROM app.identity_settings s WHERE s.id = 'installation' AND (COALESCE(t.audience, '') = '' OR t.audience = ANY(s.api_audiences) OR t.audience = ANY(s.service_audiences)))
      AND COALESCE((SELECT u.active FROM identity.users u WHERE u.id = t.user_id), false)) AS live
  FROM auth.tokens t;

CREATE OR REPLACE VIEW identity.handle_reservations AS
  SELECT x.handle, x.kind, x.subject_id FROM auth.handle_reservations x;

CREATE OR REPLACE VIEW identity.groups AS
  SELECT x.id, x.handle, x.name, x.description, x.created_by, x.created_at, x.deleted_at, x.parent_id FROM auth.groups x;

CREATE OR REPLACE VIEW identity.group_hierarchy AS
  SELECT x.id, x.revision FROM auth.group_hierarchy x;

CREATE OR REPLACE VIEW identity.group_members AS
  SELECT x.group_id, x.user_id, x.role, x.created_at FROM auth.group_members x;

CREATE OR REPLACE VIEW identity.group_invitations AS
  SELECT x.id, x.group_id, x.email, x.role, x.invited_by, x.created_at FROM auth.group_invitations x;

CREATE OR REPLACE VIEW identity.group_mail_outbox AS
  SELECT x.id, x.email, x.recipient_id, x.group_id, x.group_name, x.handle, x.action, x.sender_id, x.lease_until, x.claim_token, x.attempts, x.next_attempt_at, x.quarantined_at, x.sent_at, x.created_at FROM auth.group_mail_outbox x;

CREATE OR REPLACE VIEW identity.sessions AS
  SELECT s.id, s."expiresAt", s."createdAt", s."updatedAt", s."ipAddress", s."userAgent", s."userId", (s."expiresAt" > now()) AS live FROM auth.session s;
